        <h2 id="code-of-conduct"><strong>Code of Conduct<sup>1</sup></strong></h2>
        <h3><strong>Contents</strong></h3>
        <ul>
        <li><a href="#coc-guiding-principles">Guiding Principles</a></li>
        <li><a href="#coc-community-standards">Community Standards</a></li>
